contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We model calling C.transfer and observe whether it reverts. The general rule:
    // If _tos.length > 0 then either c.transfer(...) reverts, or it returns true.
    // If it returns true, then that implies the call completed (we observed the return true).
    // We assert that whenever _tos.length > 0 the call does not return false (i.e., it's either revert or true).

    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(_tos.length > 0);

        bool reverted;
        bool ret;
        try c.transfer(from, caddress, _tos, v) {
            reverted = false;
            // call returned successfully; read the return value by calling again is not allowed since it would have side-effects.
            // But the call signature returns (bool). The try with no return captures success but not the return value.
            // To observe the return value, make a low-level call through address(c).call with same calldata.
            // Build calldata for transfer(...)
            bytes4 sig = bytes4(keccak256("transfer(address,address,address[],uint256)"));
            (bool ok, bytes memory data) = address(c).call(abi.encodeWithSelector(sig, from, caddress, _tos, v));
            // This second call should behave identically; capture its return boolean if it succeeded.
            if (ok && data.length >= 32) {
                ret = abi.decode(data, (bool));
            } else {
                // If the call failed, mark as reverted for the purposes of our assertion
                reverted = true;
            }
        } catch {
            reverted = true;
            ret = false;
        }

        // General rule: since the contract requires _tos.length > 0, transfer must either revert or return true.
        // So it is invalid for it to return false without revert. We assert that: if not reverted then ret must be true.
        assert(reverted || ret == true);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(_tos.length > 0);

        bool reverted;
        bool returnedValue;

        // Make the state-changing call as a top-level try/catch on c.transfer
        try c.transfer(from, caddress, _tos, v) returns (bool ret) {
            reverted = false;
            returnedValue = ret;
        } catch {
            reverted = true;
            returnedValue = false;
        }

        // General rule: if the call did not revert, its returned boolean must be true.
        assert(reverted || returnedValue == true);
    }

    receive() external payable {}
}

